1	import type { Attachment, MotionMedia } from "@/types/proto/api/v1/attachment_service_pb";
2	import { MotionMediaFamily, MotionMediaRole } from "@/types/proto/api/v1/attachment_service_pb";
3	import { getAttachmentThumbnailUrl, getAttachmentType, getAttachmentUrl } from "@/utils/attachment";
4	import { buildAttachmentVisualItems } from "@/utils/media-item";
5	
6	export type FileCategory = "image" | "video" | "motion" | "audio" | "document";
7	
8	export interface AttachmentItem {
9	  readonly id: string;
10	  readonly memberIds: string[];
11	  readonly filename: string;
12	  readonly category: FileCategory;
13	  readonly mimeType: string;
14	  readonly thumbnailUrl: string;
15	  readonly sourceUrl: string;
16	  readonly size?: number;
17	  readonly isLocal: boolean;
18	  readonly isVoiceNote: boolean;
19	  readonly audioMeta?: LocalFile["audioMeta"];
20	}
21	
22	export interface LocalFile {
23	  readonly file: File;
24	  readonly previewUrl: string;
25	  readonly origin?: "audio_recording" | "upload";
26	  readonly audioMeta?: {
27	    readonly durationSeconds: number;
28	  };
29	  readonly motionMedia?: MotionMedia;
30	}
31	
32	const AUDIO_RECORDING_FILENAME_RE = /^(?:voice-(?:recording|note)|audio-recording)-(\d{8})-(\d{4,6})/i;
33	
34	export const isAudioRecordingFilename = (filename: string): boolean => AUDIO_RECORDING_FILENAME_RE.test(filename);
35	
36	export const getAudioRecordingTimeLabel = (filename: string): string | undefined => {
37	  const match = filename.match(AUDIO_RECORDING_FILENAME_RE);
38	  const timePart = match?.[2];
39	  if (!timePart) {
40	    return undefined;
41	  }
42	
43	  if (timePart.length === 4) {
44	    return `${timePart.slice(0, 2)}:${timePart.slice(2, 4)}`;
45	  }
46	
47	  if (timePart.length === 6) {
48	    return `${timePart.slice(0, 2)}:${timePart.slice(2, 4)}:${timePart.slice(4, 6)}`;
49	  }
50	
51	  return undefined;
52	};
53	
54	function categorizeFile(mimeType: string, motionMedia?: MotionMedia): FileCategory {
55	  if (motionMedia) return "motion";
56	  if (mimeType.startsWith("image/")) return "image";
57	  if (mimeType.startsWith("video/")) return "video";
58	  if (mimeType.startsWith("audio/")) return "audio";
59	  return "document";
60	}
61	
62	function attachmentGroupToItem(attachment: Attachment): AttachmentItem {
63	  const attachmentType = getAttachmentType(attachment);
64	  const sourceUrl = getAttachmentUrl(attachment);
65	
66	  return {
67	    id: attachment.name,
68	    memberIds: [attachment.name],
69	    filename: attachment.filename,
70	    category: categorizeFile(attachment.type),
71	    mimeType: attachment.type,
72	    thumbnailUrl: attachmentType === "image/*" ? getAttachmentThumbnailUrl(attachment) : sourceUrl,
73	    sourceUrl,
74	    size: Number(attachment.size),
75	    isLocal: false,
76	    isVoiceNote: categorizeFile(attachment.type) === "audio" && isAudioRecordingFilename(attachment.filename),
77	    audioMeta: undefined,
78	  };
79	}
80	
81	function visualItemToAttachmentItem(item: ReturnType<typeof buildAttachmentVisualItems>[number]): AttachmentItem {
82	  return {
83	    id: item.id,
84	    memberIds: item.attachmentNames,
85	    filename: item.filename,
86	    category: item.kind === "motion" ? "motion" : item.kind,
87	    mimeType: item.mimeType,
88	    thumbnailUrl: item.posterUrl,
89	    sourceUrl: item.sourceUrl,
90	    size: item.attachments.reduce((total, attachment) => total + Number(attachment.size), 0),
91	    isLocal: false,
92	    isVoiceNote: false,
93	    audioMeta: undefined,
94	  };
95	}
96	
97	function fileToItem(file: LocalFile): AttachmentItem {
98	  return {
99	    id: file.motionMedia?.groupId || file.previewUrl,
100	    memberIds: [file.previewUrl],
101	    filename: file.file.name,
102	    category: categorizeFile(file.file.type, file.motionMedia),
103	    mimeType: file.file.type,
104	    thumbnailUrl: file.previewUrl,
105	    sourceUrl: file.previewUrl,
106	    size: file.file.size,
107	    isLocal: true,
108	    isVoiceNote:
109	      categorizeFile(file.file.type, file.motionMedia) === "audio" &&
110	      (file.origin === "audio_recording" || isAudioRecordingFilename(file.file.name)),
111	    audioMeta: file.audioMeta,
112	  };
113	}
114	
115	function toLocalMotionItems(localFiles: LocalFile[]): AttachmentItem[] {
116	  const grouped = new Map<string, LocalFile[]>();
117	  const singles: AttachmentItem[] = [];
118	
119	  for (const localFile of localFiles) {
120	    const groupId = localFile.motionMedia?.groupId;
121	    if (!groupId) {
122	      singles.push(fileToItem(localFile));
123	      continue;
124	    }
125	
126	    const group = grouped.get(groupId) ?? [];
127	    group.push(localFile);
128	    grouped.set(groupId, group);
129	  }
130	
131	  const groupedItems = Array.from(grouped.entries()).flatMap(([groupId, files]) => {
132	    const still = files.find(
133	      (file) => file.motionMedia?.family === MotionMediaFamily.APPLE_LIVE_PHOTO && file.motionMedia.role === MotionMediaRole.STILL,
134	    );
135	    const video = files.find(
136	      (file) => file.motionMedia?.family === MotionMediaFamily.APPLE_LIVE_PHOTO && file.motionMedia.role === MotionMediaRole.VIDEO,
137	    );
138	    if (still && video && files.length === 2) {
139	      return [
140	        {
141	          id: groupId,
142	          memberIds: [still.previewUrl, video.previewUrl],
143	          filename: still.file.name,
144	          category: "motion" as const,
145	          mimeType: still.file.type,
146	          thumbnailUrl: still.previewUrl,
147	          sourceUrl: video.previewUrl,
148	          size: still.file.size + video.file.size,
149	          isLocal: true,
150	          isVoiceNote: false,
151	          audioMeta: undefined,
152	        },
153	      ];
154	    }
155	
156	    return files.map(fileToItem);
157	  });
158	
159	  return [...groupedItems, ...singles];
160	}
161	
162	export function toAttachmentItems(attachments: Attachment[], localFiles: LocalFile[] = []): AttachmentItem[] {
163	  const visualAttachments = attachments.filter((attachment) => {
164	    const attachmentType = getAttachmentType(attachment);
165	    return attachmentType === "image/*" || attachmentType === "video/*" || attachment.motionMedia !== undefined;
166	  });
167	  const attachmentVisualIds = new Set<string>();
168	  const attachmentVisualItems = buildAttachmentVisualItems(visualAttachments).map((item) => {
169	    item.attachmentNames.forEach((name) => attachmentVisualIds.add(name));
170	    return visualItemToAttachmentItem(item);
171	  });
172	
173	  const nonVisualAttachmentItems = attachments
174	    .filter((attachment) => !attachmentVisualIds.has(attachment.name))
175	    .map(attachmentGroupToItem)
176	    .filter((item) => item.category === "audio" || item.category === "document");
177	
178	  return [...attachmentVisualItems, ...nonVisualAttachmentItems, ...toLocalMotionItems(localFiles)];
179	}
180	
181	export function filterByCategory(items: AttachmentItem[], categories: FileCategory[]): AttachmentItem[] {
182	  const categorySet = new Set(categories);
183	  return items.filter((item) => categorySet.has(item.category));
184	}
185	
186	export function separateMediaAndDocs(items: AttachmentItem[]): { media: AttachmentItem[]; docs: AttachmentItem[] } {
187	  const media: AttachmentItem[] = [];
188	  const docs: AttachmentItem[] = [];
189	
190	  for (const item of items) {
191	    if (item.category === "image" || item.category === "video" || item.category === "motion") {
192	      media.push(item);
193	    } else {
194	      docs.push(item);
195	    }
196	  }
197	
198	  return { media, docs };
199	}
```

